def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            stack = [(r, c)]
            seen[r][c] = True
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            not seen[ny][nx] and grid[ny][nx] != 0):
                        seen[ny][nx] = True
                        stack.append((ny, nx))

            top = min(y for y, x in cells)
            bottom = max(y for y, x in cells)
            left = min(x for y, x in cells)
            right = max(x for y, x in cells)

            rings = []
            while top <= bottom and left <= right:
                perimeter = []
                for x in range(left, right + 1):
                    perimeter.append((top, x))
                    if bottom != top:
                        perimeter.append((bottom, x))
                for y in range(top + 1, bottom):
                    perimeter.extend(((y, left), (y, right)))

                colors = {grid[y][x] for y, x in perimeter}
                if len(colors) != 1:
                    break
                color = next(iter(colors))
                rings.append((color, perimeter))
                top += 1
                bottom -= 1
                left += 1
                right -= 1

            reversed_colors = [color for color, _ in rings][::-1]
            for (_, perimeter), color in zip(rings, reversed_colors):
                for y, x in perimeter:
                    out[y][x] = color

    return out
